export const t = (msAgo: number) => new Date(Date.now() - msAgo).toISOString();
// ?screen=login → show the signed-out login; ?screen=onboard → the onboarding wizard;
// ?screen=invited → first run WITH a pending invitation (the state that must beat the wizard).
export const screen = typeof location !== 'undefined' ? (new URLSearchParams(location.search).get('onboarding') ? 'onboard' : new URLSearchParams(location.search).get('screen')) : null;

// ── multi-workspace (0113) ───────────────────────────────────────────────────────────────────
// ?ws=2      → this identity belongs to two workspaces (the switcher appears)
// ?invite=1  → an invitation is waiting on their verified address (the Home join card)
// ?runs=N    → N agents mid-flight, so the switch sheet's derived warning has something to warn about
export const qp = (k: string) => (typeof location !== 'undefined' ? new URLSearchParams(location.search).get(k) : null);
export const MULTI_WS = qp('ws') === '2' || screen === 'invited';
export const HAS_INVITE = qp('invite') === '1' || screen === 'invited';
export const LIVE_RUNS = parseInt(qp('runs') || '0', 10);
export const MOCK_WS_ID = 'ws-acme';
export const mockWorkspaces = () => (MULTI_WS
  ? [
    { id: MOCK_WS_ID, name: 'Acme Robotics', slug: 'acme', role: 'owner', memberCount: 3, plan: 'cloud' },
    { id: 'ws-northwind', name: 'Northwind', slug: 'northwind', role: 'member', memberCount: 6, plan: 'cloud' },
  ]
  : [{ id: MOCK_WS_ID, name: 'Acme Robotics', slug: 'acme', role: 'owner', memberCount: 3, plan: 'cloud' }]);
// ?slow=<ms> delays message delivery so the load/switch skeleton stays on screen long enough to capture.
export const MSG_DELAY = typeof location !== 'undefined' ? parseInt(new URLSearchParams(location.search).get('slow') || '0', 10) : 0;

// ?update=available|downloading|ready|error drives the bottom-left auto-update card.
export const UPDATE_PHASE = typeof location !== 'undefined' ? new URLSearchParams(location.search).get('update') : null;
export const mockUpdateState = (): any => {
  if (UPDATE_PHASE === 'available') return { phase: 'available', version: '0.4.2', notes: 'Faster cold start, review-cockpit polish, and fixes.' };
  if (UPDATE_PHASE === 'downloading') return { phase: 'downloading', version: '0.4.2', percent: 46 };
  if (UPDATE_PHASE === 'ready') return { phase: 'ready', version: '0.4.2' };
  if (UPDATE_PHASE === 'error') return { phase: 'error', message: 'Could not reach the update server.' };
  return { phase: 'idle' };
};

