// ?setupcards=cloud models a FRESH cloud-first workspace — a runner, one member, no credential.
// The tracker retires itself once every card is done, so simply ADDING a runner to the mature
// fixture below completed the set and rendered nothing at all. The state worth shooting is the
// one a browser-onboarded user actually lands in, and it is the mockup's own picture: the machine
// already provisioned, the other three still to do. Only this flag's shots see it.
export const FRESH_CLOUD = qp('setupcards') === 'cloud';

export const members = FRESH_CLOUD ? [
  // a fresh workspace is one person, which is what makes "Invite your team" an ask
  { user_id: 'u-george', role: 'owner', display_name: 'george', compute: null },
] : [
  // `compute` (0118): george carries one per-agent choice so the placement table's "your pick"
  // row previews; the default stays unset so Auto renders. Mutable — setCompute writes it.
  // ?computecard=1 seeds it EMPTY instead: the join card only shows while the choice is unset.
  // ?desktopsessions=here|auto sets the desktop-only default (rule D9) the Compute row and the chip's Auto line read
  { user_id: 'u-george', role: 'owner', display_name: 'george', compute: qp('computecard') ? null : JSON.stringify({ machine: null, agents: { 'a-patch': 'm2' }, shares: ['u-maria'], ...(qp('desktopsessions') ? { desktopSessions: qp('desktopsessions') } : {}) }) },
  // a full display name — exercises the mention-handle derivation ("maria" from "Maria Gonzalez")
  { user_id: 'u-maria', role: 'member', display_name: 'Maria Gonzalez', compute: null },
  // sam LENDS to george (so m2 reads "shared with you" and the per-agent pick stays legal);
  // maria lends to nobody, which is what makes studio-linux the "not shared" case on screen
  // owns two machines (0114) — a member is not capped at one host on Cloud
  { user_id: 'u-sam', role: 'admin', display_name: 'sam', compute: JSON.stringify({ machine: null, agents: {}, shares: qp('computecard') === 'none' ? [] : ['u-george'] }) },
];

// Shared compute (0114): a workspace's agents run on MEMBERS' machines. Three rows on purpose —
// this host, a teammate's that can serve, and one that is offline — because the panel's whole job
// is telling those three states apart. Maria has none, which is the fourth case (her requests ride
// someone else's machine).
// the cloud machine follows ?machineup: up = a fresh heartbeat, otherwise last seen hours ago,
// which is what makes the machines screen's "offline · last seen …" reachable in the harness
const CLOUD_RUNNER = { id: 'm4', name: 'acme-runner', platform: 'linux', daemon_version: '0.1.0', last_seen_at: t(qp('machineup') === '1' ? 2_000 : 10_800_000), owner_user_id: null, kind: 'runner', runtimes: '["claude-code"]' };

export const machines = FRESH_CLOUD ? [CLOUD_RUNNER] : [
  // ?computecard=lent|none strips THIS host's runtimes, which is what puts the viewer in the
  // machine-less worlds the intro card's other two states exist for
  { id: 'm1', name: "george's MacBook Pro", platform: 'darwin', daemon_version: '0.1.0', last_seen_at: t(11_000), owner_user_id: 'u-george', kind: 'local', runtimes: ['lent', 'none'].includes(qp('computecard') ?? '') ? '[]' : '["claude-code","codex"]' },
  { id: 'm2', name: 'sam-mbp', platform: 'darwin', daemon_version: '0.1.0', last_seen_at: t(24_000), owner_user_id: 'u-sam', kind: 'local', runtimes: '["claude-code"]' },
  // offline, and with nothing installed — the two reasons peers stop waiting on a machine
  { id: 'm3', name: 'studio-linux', platform: 'linux', daemon_version: '0.1.0', last_seen_at: t(30_000), owner_user_id: 'u-maria', kind: 'local', runtimes: '["gemini"]' },
  // ?cloudrow=1 adds the workspace runner beside the laptops (awake with ?machineup=1) — the
  // machine chip's cloud row (rule D9) and the Compute list's "cloud" kind
  ...(qp('cloudrow') === '1' ? [CLOUD_RUNNER] : []),
];

