export const failoverWatchers = new Set<(row: unknown | null) => void>();
// The capacity-cap fly-up's row. It lives here because the fixture seed writes it, and
// the bridge clears it when the human answers — a value two modules mutate needs ONE
// home plus a setter, since an ESM import cannot be assigned.
export let mockFailover: { decision_id: string; channel_id: string; channel_slug: string; body: string } | null = null;
export const setMockFailover = (v: typeof mockFailover) => { mockFailover = v; };

export const pingFailover = () => failoverWatchers.forEach((w) => w(mockFailover));
export const NOKEY = typeof location !== 'undefined' && new URLSearchParams(location.search).get('nokey') === '1';
// ?flow=1 — the chat→task walkthrough (evidence-only, like ?home=clear): the send handler's
// scripted rex arc stands down and window.__nmFlow.advance() paces the journey instead, so a
// capture script can drive the REAL UI (type, send, click Accept) and shoot deterministic beats.
export const FLOW = typeof location !== 'undefined' && new URLSearchParams(location.search).get('flow') === '1';
export const exhaustedParam = typeof location !== 'undefined' ? new URLSearchParams(location.search).get('exhausted') : null;
if (exhaustedParam) {
  const avail = (openai: boolean, gemini: boolean) => ({
    anthropic: { installed: true, authed: true, method: 'subscription' as const },
    openai: { installed: true, authed: openai, method: (openai ? 'subscription' : null) as 'subscription' | null },
    gemini: { installed: true, authed: gemini, method: (gemini ? 'subscription' : null) as 'subscription' | null },
  });
  const resetAtIso = new Date(Date.now() + 2.8 * 3600_000).toISOString();
  const ultra = PACKS['ultracode']!.roles;
  const label = (id: string) => ({ 'claude-fable-5': 'Fable 5', 'claude-opus-4-8': 'Opus 4.8', 'claude-sonnet-5': 'Sonnet 5' } as Record<string, string>)[id] ?? id;
  const av = avail(true, false); // ChatGPT live, Gemini not connected
  const rec = exhaustedParam === 'claude'
    ? composeFailover({ exhaustedModel: 'claude-fable-5', activeRoles: ultra, exhausted: ['claude-fable-5', 'claude-opus-4-8', 'claude-sonnet-5', 'claude-sonnet-4-6', 'claude-haiku-4-5'], avail: av })
    : composeFailover({ exhaustedModel: 'claude-fable-5', activeRoles: ultra, exhausted: [], avail: av });
  const body = buildFailoverCard(rec, { exhaustedModel: 'claude-fable-5', avail: av, currentPack: 'ultracode', resetAtIso }, label).body;
  msgsByChannel['c-general']!.push({ id: 'gfo', author_kind: 'agent', author_id: 'a-rex', created_at: t(1000), body });
  // …and feed the sticky fly-up: a cap is workspace-wide, so it surfaces everywhere
  mockFailover = { decision_id: 'd-gfo', channel_id: 'c-general', channel_slug: 'general', body };
}

