// `updated_at` rides every synced task row; the fixtures omit it, so stamp a believable
// spread here — the room's History surface sorts on it, and a list of blank timestamps in
// arbitrary order is not evidence of anything.
// Thread-per-task, as production has it (docs/35): the gated tasks and the card's task get their
// thread here, so the needs-you rows can be SETTLED in the harness (settle acts on a thread —
// the bell's and the overlay's controls need `thread_id` to exist, exactly as they do live).
const GATED = new Set(['done', 'plan_review', 'design_review', 'ship_review', 'blocked']);
for (const [cid, ts] of Object.entries(tasksByChannel)) {
  for (const task of ts) {
    if (!GATED.has(task.state) && task.id !== 'tk-1046') continue;
    task.thread_id = `th-${task.id}`;
    (mockThreads[cid] ??= []).push({ id: `th-${task.id}`, title: task.title, description: task.description ?? '', created_by: 'agent:a-rex', task_id: task.id, created_at: seedIso(3 * 3_600_000), updated_at: seedIso(600_000), msg_count: 1, last_body: task.description ?? '' } as any);
  }
}

export const allTasks = Object.entries(tasksByChannel).flatMap(([cid, ts]) =>
  ts.map((task, i) => ({
    updated_at: t((i + 1) * 5 * 3_600_000),
    // who holds the ball (needsyou.ts): null = you haven't spoken since the gate opened
    last_human_msg_at: homeIsAnswered ? t(60_000) : null,
    ...task,
    channel_slug: channels.find((c) => c.id === cid)?.slug ?? 'dev',
  })),
);

