// derive run rows (newest first) from the mock logs, mirroring AgentLog.runs()
export const mockRuns = (agentId: string) => {
  const byRun = new Map<string, typeof logs>();
  for (const r of logs) if (r.run_id && r.agent_id === agentId) (byRun.get(r.run_id) ?? byRun.set(r.run_id, []).get(r.run_id)!).push(r);
  return [...byRun.entries()].map(([run_id, rs]) => {
    const sorted = [...rs].sort((a, b) => a.id - b.id);
    return { run_id, agent_id: agentId, started_at: sorted[0]!.ts, last_at: sorted[sorted.length - 1]!.ts, rows: rs.length,
      tokens: rs.reduce((s, x) => s + (x.tokens ?? 0), 0), worst_level: rs.some((x) => x.level === 'error') ? 'error' : rs.some((x) => x.level === 'warn') ? 'warn' : 'info',
      task_number: sorted.find((x) => x.task_number)?.task_number ?? null, channel_slug: sorted[0]!.channel_slug ?? null, trigger: sorted[0]!.summary };
  }).sort((a, b) => Math.max(...byRun.get(b.run_id)!.map((x) => x.id)) - Math.max(...byRun.get(a.run_id)!.map((x) => x.id)));
};
