export const noop = () => {};
/**
 * Mirror of the real room watch (sync.ts `nm:watch-messages`) after docs/35: channel-root
 * messages only (`task_id is null`), a thread's replies excluded, a thread ROOT kept and tagged
 * with `root_thread_id` — the column that tells the legacy pass this message already opened a
 * session. The docs/20 `thread_mode='off'` widening retired with the lens, and so did the inline
 * task-reply fixture that only existed to demo it.
 */
export const roomMessagesFor = (id: string) => (msgsByChannel[id] ?? [])
  .filter((m: any) => !m.task_id)
  .map((m: any) => ({
    ...m,
    thread_id: m.thread_id ?? null,
    root_thread_id: (mockThreads[id] ?? []).find((th: any) => th.root_message_id === m.id)?.id ?? null,
  }))
  .sort((a: any, b: any) => String(a.created_at).localeCompare(String(b.created_at)));
export const msgWatchers: Array<{ id: string; cb: (rows: any[]) => void }> = [];
// Preview/test-only: append a channel message and re-fire that channel's live watchers, so a
// headless Playwright run can assert the feed auto-follows a new message (issue: no auto-scroll).
// `tall` pushes a multi-line body — the case where a smooth-scroll animation used to unpin the
// reader mid-flight and drop the follow. Not part of the real bridge; harness-only.
if (typeof window !== 'undefined') {
  (window as any).__nmInjectMessage = (channelId: string, body: string, tall = false) => {
    const list = msgsByChannel[channelId] ?? (msgsByChannel[channelId] = []);
    const text = tall ? Array.from({ length: 14 }, (_, i) => `${body} · line ${i + 1}`).join('\n') : body;
    list.push({ id: `inj-${channelId}-${list.length}`, author_kind: 'agent', author_id: 'a-rex', created_at: t(-1000 * (list.length + 1)), body: text });
    msgWatchers.filter((w) => w.id === channelId).forEach((w) => w.cb(roomMessagesFor(channelId)));
    return list.length;
  };
}
