export let termSeq = 0;
// The banner's palette proof (terminal-colors round): the harness terminal renders the ANSI-16
// strip plus the exact dark-assuming output that vanished on the paper themes — dim SGR, 24-bit
// grey, yellow-on-default — so a capture can FAIL when the per-theme ramp or the contrast floor
// regresses, instead of proving an empty prompt.
export const TERM_PALETTE_PROOF =
  Array.from({ length: 8 }, (_, i) => `\x1b[3${i}m■\x1b[0m`).join(' ') + '  ' +
  Array.from({ length: 8 }, (_, i) => `\x1b[9${i}m■\x1b[0m`).join(' ') +
  '\r\n\x1b[2mdim\x1b[0m · \x1b[1mbold\x1b[0m · \x1b[7m inverse \x1b[0m · \x1b[38;2;153;153;153m24-bit grey\x1b[0m · \x1b[33myellow\x1b[0m · \x1b[31mred\x1b[0m · \x1b[32mgreen\x1b[0m · \x1b[34mblue\x1b[0m · \x1b[36mcyan\x1b[0m';
export const openMockTerm = (taskNumber: number, onData: (d: string) => void, banner: string) => {
  const subId = `t-${++termSeq}`;
  liveTerms.set(subId, { subId, taskNumber, title: taskNumber > 0 ? `#${taskNumber}` : 'terminal' });
  notifyProcs();
  setTimeout(() => onData(banner), 60);
  return { subId, input: (_d: string) => undefined, resize: (_c: number, _r: number) => undefined, close: () => { liveTerms.delete(subId); notifyProcs(); } };
};
